                    totalWords++;
                    countInside = 0;
                }
            } else {
                if (inParentheses) {
                    if (ch != '_') {
                        countInside++;
                    } else {
                        if (countInside > 0) {
                            totalWords++;
                            countInside = 0;
                        }
                    }
                } else {
                    if (ch != '_') {
                        countOutside++;
                    } else {
                        countOutside = 0;
                    }
                }
            }
            if (countOutside >= maxSequence) {
                maxSequence = countOutside;
            }
        }
        System.out.println(maxSequence);
        System.out.println(totalWords);
